import subprocess, pytest, os, random

# Path to the compiled binary
ENCODER_BINARY = "./rds_encoder"
DECODER_BINARY = "./rds_decoder"

ERR_ARG = 1
ERR_CRC = 2

@pytest.fixture(scope="session", autouse=True)
def check_binary_exists():
    """Ensure the compiled binary exists before running tests."""
    assert os.path.exists(ENCODER_BINARY), f"Encoder binary not found at {ENCODER_BINARY}"
    assert os.path.exists(DECODER_BINARY), f"Decoder binary not found at {DECODER_BINARY}"

def run_app(binary, args):
    """
    Helper function to run the application binary with arguments.
    
    Args:
        args (list): List of command-line arguments.
        input_data (str): Optional input data for stdin.

    Returns:
        CompletedProcess: The result of the subprocess run.
    """
    result = subprocess.run(
        [binary] + args,
        text=True,
        capture_output=True
    )
    return result

def arg_str2list(arg_str):
    """Convert a string of comma-separated values to a list."""
    if "\"" in arg_str:
        str_begin = arg_str.find("\"")
        str_end = arg_str.rfind("\"")
        if str_end == len(arg_str) - 1:
            return arg_str[:str_begin-1].split(" ") + [arg_str[str_begin+1:str_end]]
        return arg_str[:str_begin-1].split(" ") + [arg_str[str_begin+1:str_end]] + arg_str[str_end+2:].split(" ")
    return arg_str.split(" ")

def help_message(binary):
    """Test if the application displays a help message."""
    ARGS = ["--help", "-h", "-a --help", "abc --help", "-g 0A -pi 4660 -pty 5 -tp 1 -ms 0 -ta 1 -af 104.5,98.0 -ps RadioXYZ -h"]
    for ARG in ARGS:
        ARG = arg_str2list(ARG)
        result = run_app(binary, ARG)
        assert result.returncode == 0, "Application exited with a non-zero code"
        assert "Usage" in result.stdout or "Help" in result.stdout, "Help message not found"

def test_help_message():
    """Test if the encoder application displays a help message."""
    help_message(ENCODER_BINARY)
    help_message(DECODER_BINARY)

def test_encoder_args():
    """Test the encoder application with invalid arguments."""
    ARGS = [
        "", # No arguments
        "abc", # Unspecified arguments
        "-g",  # Argument missing a value
        # Missing a single specified argument for 0A
        "-g 0A -pty 5 -tp 1 -ms 0 -ta 1 -af 104.5,98.0 -ps \"RadioXYZ\"",
        "-g 0A -pi 4660 -tp 1 -ms 0 -ta 1 -af 104.5,98.0 -ps \"RadioXYZ\"",
        "-g 0A -pi 4660 -pty 5 -ms 0 -ta 1 -af 104.5,98.0 -ps \"RadioXYZ\"",
        "-g 0A -pi 4660 -pty 5 -tp 1 -ta 1 -af 104.5,98.0 -ps \"RadioXYZ\"",
        "-g 0A -pi 4660 -pty 5 -tp 1 -ms 0 -af 104.5,98.0 -ps \"RadioXYZ\"",
        "-g 0A -pi 4660 -pty 5 -tp 1 -ms 0 -ta 1 -ps \"RadioXYZ\"",
        "-g 0A -pi 4660 -pty 5 -tp 1 -ms 0 -ta 1 -af 104.5,98.0",
        # Invalid values for uint16 arguments
        "-g 0A -pi abc -pty 5 -tp 1 -ms 0 -ta 1 -af 104.5,98.0 -ps \"RadioXYZ\"",
        "-g 0A -pi -1 -pty 5 -tp 1 -ms 0 -ta 1 -af 104.5,98.0 -ps \"RadioXYZ\"",
        "-g 0A -pi 1000000 -pty 5 -tp 1 -ms 0 -ta 1 -af 104.5,98.0 -ps \"RadioXYZ\"",
        # Invalid values for uint5 arguments
        "-g 0A -pi 4660 -pty a -tp 1 -ms 0 -ta 1 -af 104.5,98.0 -ps \"RadioXYZ\"",
        "-g 0A -pi 4660 -pty -1 -tp 1 -ms 0 -ta 1 -af 104.5,98.0 -ps \"RadioXYZ\"",
        "-g 0A -pi 4660 -pty 32 -tp 1 -ms 0 -ta 1 -af 104.5,98.0 -ps \"RadioXYZ\"",
        # Invalid values for boolean arguments
        "-g 0A -pi 4660 -pty 5 -tp a -ms 0 -ta 1 -af 104.5,98.0 -ps \"RadioXYZ\"",
        "-g 0A -pi 4660 -pty 5 -tp 12 -ms 0 -ta 1 -af 104.5,98.0 -ps \"RadioXYZ\"",
        # Invalid values for vector arguments (af)
        "-g 0A -pi 4660 -pty 5 -tp 1 -ms 0 -ta 1 -af abc -ps \"RadioXYZ\"",
        "-g 0A -pi 4660 -pty 5 -tp 1 -ms 0 -ta 1 -af 0.0 -ps \"RadioXYZ\"",
        "-g 0A -pi 4660 -pty 5 -tp 1 -ms 0 -ta 1 -af 1000.1 -ps \"RadioXYZ\"",
        "-g 0A -pi 4660 -pty 5 -tp 1 -ms 0 -ta 1 -af 100.0,1000.1 -ps \"RadioXYZ\"",
        # Exceeding length for vector arguments (af)
        "-g 0A -pi 4660 -pty 5 -tp 1 -ms 0 -ta 1 -af 100.0,100.0,100.0,100.0,100.0,100.0,100.0,100.0,100.0 -ps \"RadioXYZ\"",
        # Exceeding length for string arguments (ps)
        "-g 0A -pi 4660 -pty 5 -tp 1 -ms 0 -ta 1 -af 100.0,100.0 -ps \"RadioXYZABCD\"",
        # Missing a single specified argument for 2A
        "-g 2A -pty 5 -tp 1 -rt \"Now Playing Song Title by Artist\" -ab 0",
        "-g 2A -pi 4660 -tp 1 -rt \"Now Playing Song Title by Artist\" -ab 0",
        "-g 2A -pi 4660 -pty 5 -rt \"Now Playing Song Title by Artist\" -ab 0",
        "-g 2A -pi 4660 -pty 5 -tp 1 -ab 0",
        "-g 2A -pi 4660 -pty 5 -tp 1 -rt \"Now Playing Song Title by Artist\"",
        # Exceeding length for string arguments (rt)
        "-g 2A -pi 4660 -pty 5 -tp 1 -ab 0 -rt " + "a"*65,
        # Double dash argument
        "--g 2A -pi 4660 -pty 5 -tp 1 -rt \"Now Playing Song Title by Artist\" -ab 0",
        "--g 0A -pi 4660 -pty 5 -tp 1 -ms 0 -ta 1 -af 104.5,98.0 -ps \"RadioXYZ\""
    ]
    for ARG in ARGS:
        ARG = arg_str2list(ARG)   
        result = run_app(ENCODER_BINARY, ARG)
        assert result.returncode == ERR_ARG, "Application exited with a zero code"

def test_decoder_args():
    """Test the decoder application with invalid arguments."""
    ARGS = [
        "",
        "abc",
        "-g",
        # Binary string with incorrect length
        "-b 101",
        "-b " + "1"*103,
        "-b " + "1"*105,
        # Non binary string
        "-b 1234567890",
        # 0A having more than 4 blocks (4 blocks = 8 characters of PS in total)
        "-b "
        # 2A having more than 16 blocks (16 blocks = 64 characters of RT in total)
        "-b ",
    ]
    for ARG in ARGS:
        ARG = arg_str2list(ARG)   
        result = run_app(DECODER_BINARY, ARG)
        assert result.returncode == ERR_ARG, "Application exited with a zero code"

def test_encoder_g0a_basic():
    """Basic test for the encoder application with 0A group type provided by the assignment"""
    arg = arg_str2list("-g 0A -pi 4660 -pty 5 -tp 1 -ms 0 -ta 1 -af 104.5,98.0 -ps \"RadioXYZ\"")
    result = run_app(ENCODER_BINARY, arg)
    arg_scrambled = arg_str2list("-af 104.5,98.0 -ta 1 -pty 5 -tp 1 -ms 0 -g 0A -ps RadioXYZ -pi 4660")
    result_scrambled = run_app(ENCODER_BINARY, arg_scrambled)
    assert result.returncode == 0, "Application exited with a non-zero code"
    assert result_scrambled.returncode == 0, "Application exited with a non-zero code"
    expected = ""
    assert result.stdout.strip() == expected, "Output does not match expected"
    assert result_scrambled.stdout.strip() == expected, "Output does not match expected"

def test_decoder_g0a_basic():
    """Basic test for the encoder application with 0A group type provided by the assignment"""
    arg = arg_str2list("-b ")
    result = run_app(DECODER_BINARY, arg)
    assert result.returncode == 0, "Application exited with a non-zero code"
    expected = "PI: 4660\nGT: 0A\nTP: 1\nPTY: 5\nTA: Active\nMS: Speech\nDI: 0\nAF: 104.5, 98.0\nPS: \"RadioXYZ\""
    assert result.stdout.strip() == expected, "Output does not match expected"

