def test_g0a_multiple_frequencies():
    """Test encoding/decoding of multiple frequencies for 0A group type"""
    enc_arg = arg_str2list("-g 0A -pi 4660 -pty 5 -tp 1 -ms 0 -ta 1 -af 104.5,98.0,104.6,98.1,104.5,98.0,104.6,98.1 -ps \"RadioXYZ\"")
    enc_result = run_app(ENCODER_BINARY, enc_arg)
    assert enc_result.returncode == 0, "Application exited with a non-zero code"
    dec_arg = arg_str2list("-b " + enc_result.stdout.strip())
    dec_result = run_app(DECODER_BINARY, dec_arg)
    assert dec_result.returncode == 0, "Application exited with a non-zero code"
    expected = "PI: 4660\nGT: 0A\nTP: 1\nPTY: 5\nTA: Active\nMS: Speech\nDI: 0\nAF: 104.5, 98.0, 104.6, 98.1, 104.5, 98.0, 104.6, 98.1\nPS: \"RadioXYZ\""
    assert dec_result.stdout.strip() == expected, "Output does not match expected"

