def test_decoder_g0a_invalid_CRC():
    """Test invalid CRC detection in decoder group 0A"""
    enc_arg = arg_str2list("-g 0A -pi 4660 -pty 5 -tp 1 -ms 0 -ta 1 -af 104.5,98.0 -ps \"RadioXYZ\"")
    enc_result = run_app(ENCODER_BINARY, enc_arg)
    assert enc_result.returncode == 0, "Application exited with a non-zero code"
    # Flip random bit at various positions in the binary string
    for i in range(len(enc_result.stdout.strip())):
        binary_string = list(enc_result.stdout.strip())
        random_change = random.randint(0, len(binary_string) - 1)
        binary_string[random_change] = "1" if binary_string[random_change] == "0" else "0"
        dec_arg = arg_str2list("-b " + "".join(binary_string))
        dec_result = run_app(DECODER_BINARY, dec_arg)
        assert dec_result.returncode == ERR_CRC, "Application exited with a non-zero code"

