def test_decoder_scramble_0A():
    """Test for the decoder application with scrambled segments for 0A group type provided by the assignment

    The segments are scrambled in the following order (examples):
        - within group: 1:[ACDB] 2:[BCDA] 3:[DBCA]
        - between groups: 2:[ABCD] 1:[ABCD] 3:[ABCD]
        - both: 3:[ACDB] 1:[BCDA] 2:[DBCA]
    """
    scrambled_args = [
        arg_str2list("-b "), 
        arg_str2list("-b "), 
        arg_str2list("-b ")
    ]
    for arg in scrambled_args:    
        dec_result = run_app(DECODER_BINARY, arg)
        assert dec_result.returncode == 0, "Application exited with a non-zero code"
        expected = "PI: 4660\nGT: 0A\nTP: 1\nPTY: 5\nTA: Active\nMS: Speech\nDI: 0\nAF: 104.6, 98.1\nPS: \"RadioXYZ\""
        assert dec_result.stdout.strip() == expected, "Output does not match expected"

